import {
  DeltakerStatusAarsakType,
  DeltakerStatusType,
  nullableDateSchema,
  Oppstartstype,
  Pameldingstype,
  tiltakskodeResponseSchema,
  Vurderingstype
} from 'deltaker-flate-common'
import { z } from 'zod'

export enum Beskyttelsesmarkering {
  FORTROLIG = 'FORTROLIG',
  STRENGT_FORTROLIG = 'STRENGT_FORTROLIG',
  STRENGT_FORTROLIG_UTLAND = 'STRENGT_FORTROLIG_UTLAND',
  SKJERMET = 'SKJERMET'
}

const deltakerStatusAarsakSchema = z.object({
  type: z.enum(DeltakerStatusAarsakType)
})

export const deltakerStatusSchema = z.object({
  type: z.enum(DeltakerStatusType),
  aarsak: deltakerStatusAarsakSchema.nullable()
})

export enum Feilkode {
  UGYLDIG_STATE = 'UGYLDIG_STATE',
  MIDLERTIDIG_FEIL = 'MIDLERTIDIG_FEIL',
  UKJENT = 'UKJENT'
}

export const deltakerSchema = z.object({
  id: z.uuid(),
  fornavn: z.string(),
  mellomnavn: z.string().nullable(),
  etternavn: z.string(),
  status: deltakerStatusSchema,
  vurdering: z.enum(Vurderingstype).nullable(),
  beskyttelsesmarkering: z.array(z.enum(Beskyttelsesmarkering)),
  navEnhet: z.string().nullable(),
  erManueltDeltMedArrangor: z.boolean(),
  feilkode: z.enum(Feilkode).nullable().optional(),
  ikkeDigitalOgManglerAdresse: z.boolean(),
  harAktiveForslag: z.boolean(),
  erNyDeltaker: z.boolean(),
  harOppdateringFraNav: z.boolean(),
  kanEndres: z.boolean(),
  soktInnDato: nullableDateSchema,
  startdato: nullableDateSchema,
  sluttdato: nullableDateSchema
})

export const deltakereSchema = z.array(deltakerSchema)

const koordinatorSchema = z.object({
  id: z.uuid(),
  navn: z.string(),
  erAktiv: z.boolean(),
  kanFjernes: z.boolean()
})

export const deltakerlisteDetaljerSchema = z.object({
  id: z.uuid(),
  navn: z.string(),
  tiltakskode: tiltakskodeResponseSchema,
  startdato: nullableDateSchema,
  sluttdato: nullableDateSchema,
  oppstartstype: z.enum(Oppstartstype).nullable(),
  apentForPamelding: z.boolean(),
  antallPlasser: z.number().nullable(),
  pameldingstype: z.enum(Pameldingstype),
  koordinatorer: z.array(koordinatorSchema),
  erEnkeltplass: z.boolean()
})

export const handlingFilterValgSchema = z.enum([
  'AktiveForslag',
  'OppdateringFraNav',
  'NyeDeltakere'
])

export const deltakerStatusTypeSchema = z.enum(DeltakerStatusType)

export const tiltaksKoordinatorDeltakerlisteRequestSchema = z.object({
  handlingFilterValg: z.array(handlingFilterValgSchema).optional(),
  statuser: z.array(deltakerStatusTypeSchema).optional()
})

export const deltakerStatusCountsSchema = z.partialRecord(
  deltakerStatusTypeSchema,
  z.int().nonnegative()
)

export const deltakerHandlingCountsSchema = z.partialRecord(
  handlingFilterValgSchema,
  z.int().nonnegative()
)

export const deltakerFilterCountsSchema = z.object({
  statusCounts: deltakerStatusCountsSchema,
  handlingCounts: deltakerHandlingCountsSchema
})

export type Deltaker = z.infer<typeof deltakerSchema>
export type Deltakere = z.infer<typeof deltakereSchema>
export type DeltakerlisteDetaljer = z.infer<typeof deltakerlisteDetaljerSchema>
export type Koordinator = z.infer<typeof koordinatorSchema>
export type TiltaksKoordinatorDeltakerlisteRequest = z.infer<
  typeof tiltaksKoordinatorDeltakerlisteRequestSchema
>
export type DeltakerStatusCounts = z.infer<typeof deltakerStatusCountsSchema>
export type DeltakerHandlingCounts = z.infer<
  typeof deltakerHandlingCountsSchema
>
export type DeltakerFilterCounts = z.infer<typeof deltakerFilterCountsSchema>
