import {
  BodyLong,
  Box,
  Button,
  ConfirmationPanel,
  Heading
} from '@navikt/ds-react'
import { DeferredFetchState, useDeferredFetch } from 'deltaker-flate-common'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { leggTilTilgang } from '../api/api'
import { useAppContext } from '../context-providers/AppContext'
import { useFocusPageLoad } from '../hooks/useFocusPageLoad'
import { getDeltakerlisteUrl } from '../navigation'

export function IkkeTilgangTilDeltakerlistePage() {
  const { ref } = useFocusPageLoad('Deltakerliste - Ikke tilgang')
  const { deltakerlisteId } = useAppContext()
  const navigate = useNavigate()
  const [confirmation, setConfirmation] = useState(false)
  const [confirmationError, setConfirmationError] = useState<
    string | undefined
  >(undefined)
  const { error, state, doFetch } = useDeferredFetch(leggTilTilgang)

  useEffect(() => {
    if (!error && state === DeferredFetchState.RESOLVED) {
      navigate(getDeltakerlisteUrl(deltakerlisteId))
    }
  }, [error, state])

  const handleClick = async () => {
    if (!confirmation) {
      setConfirmationError('Du må bekrefte ditt behov')
    } else {
      doFetch(deltakerlisteId)
    }
  }

  return (
    <Box className="flex justify-center pt-16">
      <div className="flex flex-col gap-4 max-w-screen-ax-sm">
        <Heading
          size="small"
          level="2"
          tabIndex={-1}
          ref={ref}
          className="outline-none"
        >
          Du har ikke tilgang til deltakerlisten for denne gjennomføringen
        </Heading>
        <BodyLong>
          Deltakerlisten er kun tilgjengelig for personer som har ansvar for
          oppfølging av tiltaket og som har et tjenstlig behov for å behandle
          opplysninger om deltakerne.
        </BodyLong>
        <BodyLong>
          Dersom du har behov for slik tilgang, kan du registrere deg som
          koordinator for gjennomføringen her.
        </BodyLong>
        <BodyLong>
          Når du er registrert som koordinator, vil navnet ditt vises i
          tilknytning til deltakerlisten.
        </BodyLong>
        <ConfirmationPanel
          checked={confirmation}
          error={error ?? confirmationError}
          label="Jeg bekrefter at jeg har tjenstlig behov for å se denne deltakerlisten."
          onChange={() =>
            setConfirmation((x) => {
              setConfirmationError(undefined)
              return !x
            })
          }
        />
        <Button
          loading={state === DeferredFetchState.LOADING}
          className="w-fit"
          onClick={handleClick}
        >
          Gi meg tilgang
        </Button>
      </div>
    </Box>
  )
}
